import { isString } from 'lodash-es';
import React, { useContext } from 'react';

import { DefaultMarkerIcon } from './DefaultMarkerIcon.js';
import {
  markerContentWrapper,
  reactNodeContentWrapper,
} from './MarkerAtom.sty.js';
import { MarkerSymbolWrapper } from './MarkerSymbolWrapper.js';
import { uuidv4 } from '../../../../../core/utils/uuidv4.js';
import { Flex } from '../../../../../layouts-core/flex/Flex.js';
import { BrightnessFilter } from '../../BrightnessFilter.js';
import {
  CIRCLE_MARKER_DIAMETER,
  MARKER_PROPS,
  MARKER_RADIUS,
  OUTLINE_STROKE_WIDTH,
  PILL_MARKER_HEIGHT,
} from '../constants.js';
import { AnnotationsContext } from '../context.js';
import { buildMarkerShape } from '../functions/build-marker-shape.js';
import { cropMarker } from '../functions/crop-marker.js';
import { useMarkerBrightness } from '../hooks/useMarkerBrightness.js';
import { MarkerAtomProps } from '../types/marker.js';

const MINIMUM_MARKER_WIDTH = CIRCLE_MARKER_DIAMETER;

const DefaultMarker = () => (
  <MarkerSymbolWrapper>
    <DefaultMarkerIcon />
  </MarkerSymbolWrapper>
);
/**
 * @internal
 * The Marker atomic component
 **/
export const MarkerAtom = (props: MarkerAtomProps) => {
  const {
    x,
    width: widthProp,
    color,
    onMouseEnter,
    onMouseMove,
    onMouseLeave,
    onClick,
    interactionState = 'default',
    content = <DefaultMarker />,
    contentColor,
  } = props;
  const { opacity, slope } = useMarkerBrightness(interactionState);
  const { trackWidth, clipPathId } = useContext(AnnotationsContext);

  const outOfBounds = x + widthProp < 0 || x > trackWidth;

  if (outOfBounds) {
    // filter markers out of bounds
    return null;
  }

  const width = Math.max(widthProp, MINIMUM_MARKER_WIDTH);

  const { croppedX, croppedWidth } = cropMarker(x, width, trackWidth);

  const isPillMarker = widthProp > 0;

  const markerShape = buildMarkerShape({
    width,
    x,
    commonProps: {
      fill: color,
      ...MARKER_PROPS,
    },
    shape: isPillMarker ? 'pill' : 'circle',
    clipPathId,
  });

  const id = uuidv4();
  const brightnessFilterId = `brightness_${id}`;

  return (
    <>
      <BrightnessFilter id={brightnessFilterId} slope={slope} />
      <g
        onMouseEnter={onMouseEnter}
        onMouseMove={onMouseMove}
        onMouseLeave={onMouseLeave}
        onClick={onClick}
        filter={`url(#${brightnessFilterId})`}
        opacity={opacity}
      >
        {markerShape}
        <foreignObject
          x={isPillMarker ? croppedX : x - MARKER_RADIUS}
          y={OUTLINE_STROKE_WIDTH}
          width={isPillMarker ? croppedWidth : CIRCLE_MARKER_DIAMETER}
          height={PILL_MARKER_HEIGHT}
        >
          <div
            data-testid="marker-content-wrapper"
            className={markerContentWrapper}
            style={{ color: contentColor }}
          >
            {isString(content) ? (
              content
            ) : (
              <Flex className={reactNodeContentWrapper()}>{content}</Flex>
            )}
          </div>
        </foreignObject>
      </g>
    </>
  );
};

MarkerAtom['displayName'] = 'Annotations.Marker';
